const { app, BrowserWindow } = require('electron');
const { BrowserHost } = require('D:/Packages/PI-Desktop/worktrees/owner-local-control/apps/desktop/electron/main/browser-host.ts');
const { BrowserPane } = require('D:/Packages/PI-Desktop/worktrees/owner-local-control/apps/desktop/electron/main/browser-view.ts');
const { mkdirSync, writeFileSync, appendFileSync } = require('node:fs');
const { join } = require('node:path');
const directory=process.env.BROWSER_BASELINE_DIR;
app.setPath('userData',join(directory,'profile'));
app.on('window-all-closed',()=>{});
app.whenReady().then(async()=>{
  let window,host;
  const log=value=>appendFileSync(join(directory,'steps.log'),value+'\n');
  try{
    const workspace=join(directory,'workspace');mkdirSync(workspace,{recursive:true});
    const path=join(workspace,'index.html');
    writeFileSync(path,'<!doctype html><title>Fixture</title><body style="background:#2563eb;color:white"><label for="note">Note</label><input id="note"><button onclick="window.count++">Increment</button><script>window.count=0</script>');
    window=new BrowserWindow({show:true,width:900,height:650,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false}});
    await window.loadURL('data:text/html,<h1>Isolated browser baseline</h1>');
    const panes=[];
    host=new BrowserHost({isAdmissionClosed:()=>false,createPane:(state,open,owner)=>{const pane=new BrowserPane(state,open,undefined,owner);panes.push(pane);return pane},isPluginLoaded:()=>true,getFileRoots:async()=>[workspace],onState(){},onRevealView(){}});
    host.setWindow(window);
    await host.navigate({path},'A');
    const snapshot=await host.snapshot('A');
    const input=snapshot.tree.match(/- (e\d+) textbox "Note"/)?.[1],button=snapshot.tree.match(/- (e\d+) button "Increment"/)?.[1];
    await host.fill(input,'draft','A');host.setChromeSession('B','blank');await host.click(button,'A');
    log('count='+await host.evaluate('window.count','A'));
    const wc=panes[0].getWebContents(),send=wc.debugger.sendCommand.bind(wc.debugger);
    wc.debugger.sendCommand=async(method,params)=>{log('send '+method);const value=await send(method,params);log('done '+method);return value};
    const image=await host.screenshot({fullPage:true},'A');log('image bytes='+image.data.length);
    writeFileSync(join(directory,'result.json'),JSON.stringify({status:'PASS'}));
    return 0;
  }catch(error){log(String(error));writeFileSync(join(directory,'result.json'),JSON.stringify({status:'FAIL',error:String(error)}));return 1}
  finally{host?.dispose();if(window&&!window.isDestroyed())window.destroy()}
}).then(code=>app.exit(code),error=>{console.error(error);app.exit(1)});

